suppressPackageStartupMessages(library(data.table));w<-'independent_validation';out<-'supplementary_data/independent_HepG2';dir.create(out,recursive=TRUE,showWarnings=FALSE)
files<-c('HepG2_gene_effects.tsv','frozen_metadata_cohorts.tsv','primary_Holm5.tsv','all_ordering_results.tsv','all_fixed_baseline_metrics.tsv','all100_module_priority_metrics.tsv','shared_GEM_intervals.tsv','figure_panel_a_source.tsv','figure_panel_b_source.tsv','figure_panel_c_source.tsv','figure_panel_d_source.tsv','assayed_frozen_universe.tsv')
for(n in files)file.copy(file.path(w,n),file.path(out,n),overwrite=TRUE)
p0<-fread(file.path(out,'primary_Holm5.tsv'));p0[,`:=`(p_role=ifelse(estimable,'MonteCarlo_test','correction_placeholder_unestimable'),reported_raw_p=ifelse(estimable,raw_p,NA_real_))];fwrite(p0,file.path(out,'primary_Holm5.tsv'),sep='\t')
spec<-readRDS('reconstruction/cross_dataset/phase2_upr_rpe1/phase2_axis_spec.rds');fwrite(data.table(gene=spec$UPR$positive),file.path(out,'frozen_UPR90_members.tsv'),sep='\t');u<-fread('reconstruction/cross_dataset/phase2_upr_rpe1/phase2_gene_universe.tsv')[[1]];uu<-fread(file.path(w,'assayed_frozen_universe.tsv'))[[1]];fwrite(data.table(gene=setdiff(u,uu)),file.path(out,'unavailable_library_members.tsv'),sep='\t')
rk<-fread('reconstruction/cross_dataset/phase2_upr_rpe1/all_source_comparator_rankings.tsv');fwrite(rk,file.path(out,'frozen_source_rankings.tsv'),sep='\t')
un<-fread(file.path(w,'uniform10000_reference_draws.tsv.gz'));ss<-un[,.(draws=.N,Precision_mean=mean(Precision),Precision_low=quantile(Precision,.025),Precision_high=quantile(Precision,.975),NDCG_mean=mean(NDCG),NDCG_low=quantile(NDCG,.025),NDCG_high=quantile(NDCG,.975),gap_mean=mean(gap),gap_low=quantile(gap,.025),gap_high=quantile(gap,.975)),by=.(mode,minimum_cells,K)];fwrite(ss,file.path(out,'uniform_reference_summaries.tsv'),sep='\t')
m<-fread(file.path(w,'all_fixed_baseline_metrics.tsv'));n<-fread(file.path(w,'all100_module_priority_metrics.tsv'));cal<-list();for(i in seq_len(nrow(m[method=='UPR_priority']))){z<-m[method=='UPR_priority'][i];for(metric in c('Precision','NDCG','gap')){v<-n[mode==z$mode&minimum_cells==z$minimum_cells&K==z$K][[metric]];v<-v[is.finite(v)];ob<-z[[metric]];cal[[length(cal)+1]]<-data.table(mode=z$mode,minimum_cells=z$minimum_cells,K=z$K,metric=metric,observed=ob,finite_nulls=length(v),null_median=if(length(v))median(v)else NA_real_,upper_tail=if(is.finite(ob)&&length(v))(1+sum(v>=ob))/(1+length(v))else NA_real_)}};fwrite(rbindlist(cal),file.path(out,'matched_module_priority_calibration.tsv'),sep='\t')
b<-fread(file.path(w,'literal_list_gene_intervals.tsv'));b[,`:=`(projected_low=low,projected_high=high)];b[metric%in%c('Precision','NDCG'),`:=`(projected_low=pmax(0,low),projected_high=pmin(1,high))];b[metric=='weighted_minus_raw_NDCG',`:=`(projected_low=pmax(-1,low),projected_high=pmin(1,high))];fwrite(b,file.path(out,'literal_list_intervals_with_parameter_bounds.tsv'),sep='\t')
# Submission tables preserve every cohort, normalization mode, failure and null.
idx<-rbindlist(lapply(setdiff(list.files(out,pattern='\\.tsv$',full.names=TRUE),file.path(out,'table_index.tsv')),function(p){z<-fread(p);data.table(file=basename(p),rows=nrow(z),columns=ncol(z),description='Frozen independent HepG2 evaluation; primary versus low-support/normalization/strict sensitivity explicitly identified')}));fwrite(idx,file.path(out,'table_index.tsv'),sep='\t');rootidx<-fread('supplementary_data/table_index.tsv');rootidx<-rootidx[!startsWith(file,'independent_HepG2/')];idx[,file:=paste0('independent_HepG2/',file)];fwrite(rbind(rootidx,idx,fill=TRUE),'supplementary_data/table_index.tsv',sep='\t')
# Twenty preselected candidates, including both low-support members.
z<-fread(file.path(w,'figure_panel_b_source.tsv'));lines<-sprintf('%d & %s & %d & %.3f & %s\\\\',z$rank,z$gene,z$cells,z$effect,ifelse(z$cells>=30,'Yes','No'));writeLines(lines,file.path(w,'top20_table_rows.tex'))
